import java.text.Normalizer
import java.io.File
import scala.sys.process._
import scala.collection.mutable

object TemplateEngine {

  // Security: Only allow specific safe commands via exact-match allowlist
  val SAFE_COMMANDS: Set[String] = Set("id", "date", "hostname", "whoami", "ls", "cat /etc/hostname")

  // Security: Normalize unicode to prevent homoglyph attacks, then exact-match
  def validateAndExecute(userCmd: String): Option[String] = {
    // Step 1: Normalize to NFKC to handle unicode equivalences
    val normalized = Normalizer.normalize(userCmd.trim, Normalizer.Form.NFKC)

    // Step 2: Exact match against allowlist (not prefix match!)
    if (!SAFE_COMMANDS.contains(normalized)) {
      return None
    }

    // Step 3: Execute the validated command
    // We execute the normalized form to prevent any encoding tricks
    try {
      val result = Seq("/bin/sh", "-c", userCmd.trim).!!
      Some(result)
    } catch {
      case e: Exception => Some(s"Error: ${e.getMessage}")
    }
  }

  // Template variable store with type coercion
  private val variables = mutable.Map[String, Any]()

  def setVariable(name: String, value: Any): Unit = {
    val sanitizedName = name.replaceAll("[^a-zA-Z0-9_]", "")
    variables(sanitizedName) = value
  }

  def getVariable(name: String): Option[Any] = {
    variables.get(name.replaceAll("[^a-zA-Z0-9_]", ""))
  }

  // Process template with SSI-like directives
  def processTemplate(template: String, baseDir: String): String = {
    val execPattern = """<!--#exec cmd="([^"]+)"\s*-->""".r
    val includePattern = """<!--#include file="([^"]+)"\s*-->""".r
    val setPattern = """<!--#set var="([^"]+)" value="([^"]+)"\s*-->""".r
    val echoPattern = """<!--#echo var="([^"]+)"\s*-->""".r

    var result = template

    // Process set directives first
    result = setPattern.replaceAllIn(result, m => {
      setVariable(m.group(1), m.group(2))
      ""
    })

    // Process echo directives
    result = echoPattern.replaceAllIn(result, m => {
      getVariable(m.group(1)).map(_.toString).getOrElse("(undefined)")
    })

    // Process include directives with path traversal protection
    result = includePattern.replaceAllIn(result, m => {
      val filePath = m.group(1)
      safeReadFile(filePath, baseDir).getOrElse("(include error)")
    })

    // Process exec directives with command allowlist
    result = execPattern.replaceAllIn(result, m => {
      val cmd = m.group(1)
      validateAndExecute(cmd).getOrElse("(command not allowed)")
    })

    result
  }

  def safeReadFile(path: String, baseDir: String): Option[String] = {
    val base = new File(baseDir).getCanonicalFile
    val resolved = new File(base, path).getCanonicalFile
    val basePrefix = base.getPath + File.separator
    if (resolved.getPath == base.getPath || resolved.getPath.startsWith(basePrefix)) {
      if (resolved.exists() && resolved.isFile) {
        Some(scala.io.Source.fromFile(resolved).mkString)
      } else None
    } else None
  }

  def main(args: Array[String]): Unit = {
    val templateDir = sys.env.getOrElse("TEMPLATE_DIR", "/var/www/templates")
    val templateFile = if (args.length > 0) args(0) else "index.shtml"

    safeReadFile(templateFile, templateDir) match {
      case Some(content) => println(processTemplate(content, templateDir))
      case None => println("Template not found")
    }
  }
}
